import{_ as e,o as n,c as r,a3 as a}from"./chunks/framework.DXf0zkj5.js";const m=JSON.parse('{"title":"Edge Security Architecture & OWASP Top 10 Audit","description":"","frontmatter":{},"headers":[],"relativePath":"06-security.md","filePath":"06-security.md"}'),o={name:"06-security.md"};function i(s,t,d,l,c,g){return n(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="edge-security-architecture-owasp-top-10-audit" tabindex="-1">Edge Security Architecture &amp; OWASP Top 10 Audit <a class="header-anchor" href="#edge-security-architecture-owasp-top-10-audit" aria-label="Permalink to &quot;Edge Security Architecture &amp; OWASP Top 10 Audit&quot;">​</a></h1><h2 id="_1-owasp-top-10-mapping-defenses" tabindex="-1">1. OWASP Top 10 Mapping &amp; Defenses <a class="header-anchor" href="#_1-owasp-top-10-mapping-defenses" aria-label="Permalink to &quot;1. OWASP Top 10 Mapping &amp; Defenses&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">OWASP Vulnerability</th><th style="text-align:left;">Risk in CDN Caching Proxy</th><th style="text-align:left;">Implemented Defense in Code</th><th style="text-align:left;">Status</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>A01: Broken Access Control</strong></td><td style="text-align:left;">Unauthorized cache purging or origin draining.</td><td style="text-align:left;">Token scope validation in <code>src/purge/api.ts:60</code> enforcing <code>purge:url</code>, <code>purge:tag</code> permissions.</td><td style="text-align:left;"><strong>Implemented</strong></td></tr><tr><td style="text-align:left;"><strong>A02: Cryptographic Failures</strong></td><td style="text-align:left;">Eavesdropping on edge traffic or certificate forgery.</td><td style="text-align:left;">Dynamic TLS termination (<code>src/tls/cert-watcher.ts</code>) supporting TLS 1.3 and strong ciphers.</td><td style="text-align:left;"><strong>Implemented</strong></td></tr><tr><td style="text-align:left;"><strong>A03: Injection</strong></td><td style="text-align:left;">Header injection or cache poisoning via unescaped delimiters.</td><td style="text-align:left;">Canonical URL normalization (<code>src/proxy/normalize-url.ts</code>) and strict header validation.</td><td style="text-align:left;"><strong>Implemented</strong></td></tr><tr><td style="text-align:left;"><strong>A04: Insecure Design</strong></td><td style="text-align:left;">Thundering herd DDoS attacking upstream origin.</td><td style="text-align:left;">Request coalescing (<code>src/proxy/coalesce.ts</code>) collapsing misses into a single flight.</td><td style="text-align:left;"><strong>Implemented</strong></td></tr><tr><td style="text-align:left;"><strong>A05: Security Misconfiguration</strong></td><td style="text-align:left;">Verbose stack traces exposed to public clients.</td><td style="text-align:left;">Centralized error masking in <code>src/proxy/error-response.ts</code> hiding internal stack traces.</td><td style="text-align:left;"><strong>Implemented</strong></td></tr><tr><td style="text-align:left;"><strong>A06: Vulnerable Components</strong></td><td style="text-align:left;">Outdated third-party npm packages.</td><td style="text-align:left;">Minimal dependency tree (only <code>zod</code> in production dependencies).</td><td style="text-align:left;"><strong>Implemented</strong></td></tr><tr><td style="text-align:left;"><strong>A07: Identification &amp; Auth</strong></td><td style="text-align:left;">Spoofed admin API calls or unauthorized proxy use.</td><td style="text-align:left;">Scoped Bearer tokens for admin API and JWT/OIDC validation for edge ingress.</td><td style="text-align:left;"><strong>Implemented</strong></td></tr><tr><td style="text-align:left;"><strong>A08: Software &amp; Data Integrity</strong></td><td style="text-align:left;">Tampering with cache invalidation audit logs.</td><td style="text-align:left;">Cryptographic SHA-256 hash-chained audit trail (<code>src/purge/audit.ts</code>).</td><td style="text-align:left;"><strong>Implemented</strong></td></tr><tr><td style="text-align:left;"><strong>A09: Logging &amp; Monitoring</strong></td><td style="text-align:left;">Silent failures during origin outages or attack traffic.</td><td style="text-align:left;">Structured JSON request logging and Prometheus error counters (<code>src/observability/</code>).</td><td style="text-align:left;"><strong>Implemented</strong></td></tr><tr><td style="text-align:left;"><strong>A10: SSRF</strong></td><td style="text-align:left;">Attacker forcing proxy to request internal cloud metadata.</td><td style="text-align:left;">SSRF destination validator (<code>src/security/origin-access.ts</code>) blocking loopback and private IPs.</td><td style="text-align:left;"><strong>Implemented</strong></td></tr></tbody></table><hr><h2 id="_2-specialized-cdn-edge-defenses" tabindex="-1">2. Specialized CDN Edge Defenses <a class="header-anchor" href="#_2-specialized-cdn-edge-defenses" aria-label="Permalink to &quot;2. Specialized CDN Edge Defenses&quot;">​</a></h2><h3 id="_2-1-cache-poisoning-prevention" tabindex="-1">2.1 Cache Poisoning Prevention <a class="header-anchor" href="#_2-1-cache-poisoning-prevention" aria-label="Permalink to &quot;2.1 Cache Poisoning Prevention&quot;">​</a></h3><ul><li><strong>Canonical Key Generation</strong>: Query parameters are deterministically sorted (<code>?a=1&amp;b=2</code> vs <code>?b=2&amp;a=1</code>), scheme and hostname are lowercased, and duplicate slashes stripped.</li><li><strong>Vary Header Isolation</strong>: Cached variants are keyed by secondary headers (<code>Vary: Accept-Encoding, User-Agent</code>). An attacker cannot poison a Gzip response into a Brotli client.</li></ul><h3 id="_2-2-decompression-bomb-protection" tabindex="-1">2.2 Decompression Bomb Protection <a class="header-anchor" href="#_2-2-decompression-bomb-protection" aria-label="Permalink to &quot;2.2 Decompression Bomb Protection&quot;">​</a></h3><ul><li>In <code>src/compression/codecs.ts</code>, the <code>DecompressionBombLimiter</code> transform stream tracks decompressed bytes in real-time. If an uncompressed stream exceeds 100 MB, the stream is aborted with HTTP 502 to prevent memory exhaustion.</li></ul>',9)])])}const f=e(o,[["render",i]]);export{m as __pageData,f as default};
